import assert from 'node:assert/strict';
import { mkdirSync, mkdtempSync, writeFileSync, readFileSync, realpathSync } from 'node:fs';
import path from 'node:path';
const base='/tmp/effectory-harness-discovery';
const repo=realpathSync(mkdtempSync(path.join(base,'project-')));
const binary='/tmp/effectory-format2-upgrade/release-bin/effectory-darwin-arm64';
const run=async(args,cwd=repo)=>{
 const p=Bun.spawn(args,{cwd,stdin:'ignore',stdout:'pipe',stderr:'pipe'});const timer=setTimeout(()=>p.kill('SIGKILL'),45000);
 try {const [code,out,err]=await Promise.all([p.exited,new Response(p.stdout).text(),new Response(p.stderr).text()]);assert.equal(code,0,err.slice(0,1000));return out;} finally{clearTimeout(timer);}
};
await run([binary,'init',repo]);await run(['git','init','--quiet']);
writeFileSync(path.join(repo,'AGENTS.md'),'Effectory discovery probe root marker: ROOT_ONLY_7e6bf8\n');
await run([binary,'agent','setup','--harness','codex','--harness','claude-code','--repository',repo,'--json']);
mkdirSync(path.join(repo,'nested'));
const results=[];
for(const cwd of [repo,path.join(repo,'nested')]){
 const out=await run(['codex','debug','prompt-input'],cwd);
 const parsed=JSON.parse(out);const text=JSON.stringify(parsed);
 const hit={cwd,rootMarker:text.includes('ROOT_ONLY_7e6bf8'),skill:text.includes('effectory-build'),skillPath:text.includes(repo+'/.agents/skills') && text.includes('/effectory-build/SKILL.md'),managedGuidance:text.includes('Effectory')};
 assert.ok(hit.rootMarker && hit.skill && hit.skillPath && hit.managedGuidance,JSON.stringify(hit));results.push(hit);
}
writeFileSync(path.join(repo,'AGENTS.override.md'),'Effectory discovery probe override marker: OVERRIDE_ONLY_1c2a99\n');
await run([binary,'agent','setup','--repository',repo,'--json']);
const override=JSON.stringify(JSON.parse(await run(['codex','debug','prompt-input'])));
const hit={overrideMarker:override.includes('OVERRIDE_ONLY_1c2a99'),rootMarker:override.includes('ROOT_ONLY_7e6bf8'),skillPath:override.includes(repo+'/.agents/skills') && override.includes('/effectory-build/SKILL.md')};
assert.ok(hit.overrideMarker && !hit.rootMarker && hit.skillPath,JSON.stringify(hit));
await run([binary,'agent','remove','--harness','codex','--repository',repo,'--json']);
const removed=JSON.stringify(JSON.parse(await run(['codex','debug','prompt-input'])));
assert.ok(!removed.includes('- effectory-build:') && removed.includes('OVERRIDE_ONLY_1c2a99'));
await run([binary,'agent','setup','--harness','codex','--repository',repo,'--json']);
const result={removal:{skillAbsent:true,userOverridePreserved:true},repo,codexVersion:(await run(['codex','--version'])).trim(),results,override:hit,scope:'Local prompt-rendering diagnostic only; no model turn, delegation or user prompt was submitted. Raw global instruction/config content is not retained.'};
writeFileSync(path.join(base,'codex-result.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));

