import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { query } from './sdk/node_modules/@anthropic-ai/claude-agent-sdk/sdk.mjs';
const base='/tmp/effectory-harness-discovery';
const {repo}=JSON.parse(readFileSync(path.join(base,'codex-result.json'),'utf8'));
const results=[];
async function inspect(cwd,settingSources){
 let release;const done=new Promise(r=>release=r);let prompts=0;
 async function* input(){await done;return;}
 const q=query({prompt:input(),options:{cwd,pathToClaudeCodeExecutable:'/Users/davidr/.local/bin/claude',settingSources,persistSession:false,strictMcpConfig:true,mcpServers:{},tools:["Skill"],settings:{disableAllHooks:true,skillsSync:false,pluginSync:false},env:{...process.env,CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC:'1'}}});
 const timer=setTimeout(()=>{q.close();release();},45000);
 try {
  const init=await q.initializationResult();
  const commands=await q.supportedCommands();
  const usage=await q.getContextUsage({detail:'summary'});
  const result={cwd,settingSources,version:init.claude_code_version??null,commands:commands.filter(x=>x.name==='effectory-build'),skills:(usage.skills?.skillFrontmatter??[]).filter(x=>x.name==='effectory-build'),memoryFiles:usage.memoryFiles.filter(x=>x.path.includes('effectory.md')),apiUsage:usage.apiUsage,promptsSubmitted:prompts};
  results.push(result);return result;
 } finally {clearTimeout(timer);q.close();release();}
}
for(const cwd of [repo,path.join(repo,'nested')]){
 const r=await inspect(cwd,['project']);
 assert.equal(r.commands.length,1,JSON.stringify(r));
 assert.equal(r.skills.length,1,JSON.stringify(r));
 assert.equal(r.memoryFiles.length,1,JSON.stringify(r));
}
const excluded=await inspect(repo,[]);
assert.equal(excluded.commands.length,0);assert.equal(excluded.memoryFiles.length,0);
const result={repo,results,scope:'Local SDK initialization, supportedCommands and summary context metadata only. The input iterator yields no user messages; no model turn or token-count API request is submitted. Project settings are isolated, hooks and MCP disabled, persistence off. This is not a model authoring evaluation.'};
writeFileSync(path.join(base,'claude-result.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));

