import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
const base='/tmp/effectory-harness-discovery';const {repo}=JSON.parse(readFileSync(path.join(base,'codex-result.json'),'utf8'));
const root=path.join(repo,'AGENTS.md');const override=path.join(repo,'AGENTS.override.md');
const old=readFileSync(root,'utf8');const block=old.match(/<!-- effectory:begin -->[\s\S]*?<!-- effectory:end -->\n?/)[0];assert.equal(readFileSync(override,'utf8'),'');
const render=async()=>{const p=Bun.spawn(['codex','debug','prompt-input'],{cwd:repo,stdin:'ignore',stdout:'pipe',stderr:'pipe'});const timer=setTimeout(()=>p.kill('SIGKILL'),45000);try{const [code,out,err]=await Promise.all([p.exited,new Response(p.stdout).text(),new Response(p.stderr).text()]);assert.equal(code,0,err.slice(0,500));const text=JSON.stringify(JSON.parse(out));return {instructionLoaded:text.includes('Use the effectory-build skill when authoring or maintaining'),skillListed:text.includes('- effectory-build:'),rootCanaryLoaded:text.includes('ROOT_ONLY_7e6bf8')};}finally{clearTimeout(timer);}};
const before=await render();assert.equal(before.instructionLoaded,false);
writeFileSync(root,old.replace(block,''));writeFileSync(override,block);
try {
 const after=await render();assert.equal(after.instructionLoaded,true);assert.equal(after.skillListed,true);
 assert.ok(readFileSync(root,'utf8').includes('ROOT_ONLY_7e6bf8'));
 const result={repo,before,after,rootUserTextPreserved:true,scope:'Manual file-layout stand-in only; the production planner and ownership manifest were not modified. No model turn was submitted.'};
 writeFileSync(path.join(base,'empty-candidate-result.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));
}finally{writeFileSync(root,old);writeFileSync(override,'');}
